// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address depositor, uint256 firstAmount, uint256 secondAmount) public {
        vm.assume(depositor != address(0));
        firstAmount = bound(firstAmount, 0, 1 ether);
        secondAmount = bound(secondAmount, 0, 1 ether);

        vm.deal(depositor, firstAmount + secondAmount);

        vm.prank(depositor);
        c.addToBalance{value: firstAmount}();

        vm.prank(depositor);
        c.addToBalance{value: secondAmount}();

        assertTrue(c.getBalance(depositor) == firstAmount + secondAmount);
    }
}
